<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ArrowLeft, Save } from 'lucide-vue-next';
import AppLayout from '../../Layouts/AppLayout.vue';

defineOptions({ layout: AppLayout });
const props = defineProps({ units: Array });
const form = useForm({ name: '', sku: '', barcode: '', category: '', brand: '', unit: props.units?.[0] || 'piece', price: '', cost_price: '', wholesale_price: '', price_label: 'Retail', description: '', stock: '', reorder_level: 10 });
const submit = () => form.post('/inventory');
</script>

<template>
    <Head title="Add product" />
    <div class="page-heading"><div><p class="eyebrow"><span class="dot" /> Inventory setup</p><h1>Add a product.</h1><p>Give your team a clean, recognizable record to work from.</p></div><Link href="/inventory" class="btn btn-ghost"><ArrowLeft :size="15" /> Back to inventory</Link></div>
    <section class="card form-card"><div class="card-header" style="padding:0 0 20px"><div><h2>Product details</h2><p>Metadata makes search, labels and branch operations more useful.</p></div></div><form class="form-grid" @submit.prevent="submit"><div class="field full"><label for="name">Product name</label><input id="name" v-model="form.name" placeholder="e.g. Premium Basmati Rice 25kg" /><small v-if="form.errors.name" class="form-error">{{ form.errors.name }}</small></div><div class="field"><label for="sku">SKU</label><input id="sku" v-model="form.sku" placeholder="GRC-0251" /><small v-if="form.errors.sku" class="form-error">{{ form.errors.sku }}</small></div><div class="field"><label for="barcode">Barcode</label><input id="barcode" v-model="form.barcode" placeholder="890025100251" /><small v-if="form.errors.barcode" class="form-error">{{ form.errors.barcode }}</small></div><div class="field"><label for="category">Category</label><input id="category" v-model="form.category" placeholder="Grocery" /><small v-if="form.errors.category" class="form-error">{{ form.errors.category }}</small></div><div class="field"><label for="brand">Brand</label><input id="brand" v-model="form.brand" placeholder="Premium Harvest" /></div><div class="field"><label for="unit">Unit</label><select id="unit" v-model="form.unit"><option v-for="unit in units" :key="unit" :value="unit">{{ unit }}</option></select></div><div class="field"><label for="price">Selling price (BDT)</label><input id="price" v-model="form.price" type="number" min="0" step="0.01" placeholder="3450" /><small v-if="form.errors.price" class="form-error">{{ form.errors.price }}</small></div><div class="field"><label for="cost_price">Cost price</label><input id="cost_price" v-model="form.cost_price" type="number" min="0" step="0.01" placeholder="2950" /></div><div class="field"><label for="wholesale_price">Wholesale price</label><input id="wholesale_price" v-model="form.wholesale_price" type="number" min="0" step="0.01" placeholder="3200" /></div><div class="field"><label for="price_label">Price label</label><input id="price_label" v-model="form.price_label" placeholder="Retail / MRP" /></div><div class="field"><label for="stock">Opening stock</label><input id="stock" v-model="form.stock" type="number" min="0" placeholder="42" /><small v-if="form.errors.stock" class="form-error">{{ form.errors.stock }}</small></div><div class="field"><label for="reorder_level">Reorder level</label><input id="reorder_level" v-model="form.reorder_level" type="number" min="0" /><small v-if="form.errors.reorder_level" class="form-error">{{ form.errors.reorder_level }}</small></div><div class="field full"><label for="description">Description</label><input id="description" v-model="form.description" placeholder="Optional product notes for branch teams" /></div><div class="form-actions field full"><Link href="/inventory" class="btn btn-ghost">Cancel</Link><button class="btn btn-primary" type="submit" :disabled="form.processing"><Save :size="15" /> {{ form.processing ? 'Saving…' : 'Save product' }}</button></div></form></section>
</template>
